                                                                                                                                                                                                       
  CREATE TABLE "PM_USER"                                                                                                                                                                     
   (	"USER_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 293 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                 
	"MOBILE" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                               
	"JOB_NUMBER" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                           
	"PASSWORD" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                             
	"EMAIL" NVARCHAR2(32),                                                                                                                                                                                
	"EXT_USER_ID" NVARCHAR2(256),                                                                                                                                                                         
	"UNION_ID" NVARCHAR2(256),                                                                                                                                                                            
	"IS_LEAVE" NUMBER DEFAULT 0,                                                                                                                                                                          
	"REMARK" NVARCHAR2(1024),                                                                                                                                                                             
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                          
	"TENANT_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                   
	"CREATED_BY" NUMBER(30,0) NOT NULL ENABLE,                                                                                                                                                            
	"CREATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                  
	"UPDATED_BY" NUMBER(30,0),                                                                                                                                                                            
	"UPDATED_DATE" DATE DEFAULT sysdate,                                                                                                                                                                  
	"LAST_LOGIN_TIME" DATE,                                                                                                                                                                               
	 PRIMARY KEY ("USER_ID")                                                                                                                                                                              
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

